def solve(n, edges):
    components = {i: {i} for i in range(n)}
    for u, v in edges:
        for component_u in components:
            if u in components[component_u]:
                for component_v in components:
                    if v in components[component_v]:
                        components[component_u].update(components[component_v])
                        for key in components:
                            if key != component_u and components[key].issubset(components[component_u]):
                                components[key].clear()
                                components[component_u].update(components[key])
                        break
                break
    return len({frozenset(c) for c in components.values() if c})

