def solve(nums, target):
    first = -1
    last = -1
    for i, num in enumerate(nums):
        if num == target:
            first = i
            break
    if first == -1:
        return [-1, -1]
    for i, num in reversed(list(enumerate(nums))):
        if num == target:
            last = i
            break
    return [first, last]
